<?php
$root=$argv[1];$url=getenv('FIXTURE_URL');if($url!=='http://127.0.0.1:9438')throw new RuntimeException('Separate held-out loopback fixture required');$_SERVER['HTTP_HOST']='127.0.0.1:9438';require $root.'/wp-load.php';wp_set_current_user(1);
if(get_stylesheet()!=='twentytwentyfive'||!class_exists('WPCF7_ContactForm'))throw new RuntimeException('Expected installed block-theme CF7 fixture');
$definitions=[
 'studio-news'=>['Studio news','<fieldset><legend>Newsletter preferences</legend><p><label>Full name [text* full-name minlength:2 maxlength:60 autocomplete:name placeholder "Your name"]</label></p><p><label>Email address [email* subscriber-email autocomplete:email]</label></p><p><label>Topics [select* topics multiple "Architecture" "Materials" "Workshops"]</label></p><p>[acceptance newsletter-policy]I agree to receive studio updates.[/acceptance]</p><p>[submit "Subscribe"]</p></fieldset>'],
 'studio-visit'=>['Plan a studio visit','<p><label>Telephone [tel* telephone minlength:8 maxlength:25 autocomplete:tel]</label></p><p><label>Website [url website]</label></p><p><label>Visitors [number* visitors min:2 max:12 step:2]</label></p><p><label>Visit date [date* visit-date min:2027-02-01 max:2027-10-31]</label></p><fieldset><legend>Available days</legend>[checkbox* weekdays use_label_element "Tuesday" "Thursday" "Saturday"]</fieldset><p><label>Brief (PDF or text) [file* brief limit:128kb filetypes:pdf|txt]</label></p><p><label>Notes [textarea notes maxlength:120]</label></p><p>[submit "Request a visit"]</p>']
];$records=[];
foreach($definitions as $slug=>$definition){$existing=get_page_by_path($slug);if($existing)throw new RuntimeException('Held-out fixture is immutable after seeding');$form=WPCF7_ContactForm::get_template();$form->set_title($definition[0]);$form->set_properties(['form'=>$definition[1]]);$id=$form->save();$content='<!-- wp:paragraph --><p>Independent block-theme fixture. No messages are delivered.</p><!-- /wp:paragraph --><!-- wp:shortcode -->[contact-form-7 id="'.$id.'" title="'.$definition[0].'"]<!-- /wp:shortcode -->';$page=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$definition[0],'post_name'=>$slug,'post_content'=>$content]);$records[]=['formId'=>$id,'pageId'=>$page,'url'=>get_permalink($page),'definition'=>$definition[1]];}
flush_rewrite_rules();file_put_contents(dirname($root).'/heldout-form-records.json',json_encode($records,JSON_PRETTY_PRINT));echo json_encode($records)."\n";
